/*
 * Every pin, bus instance and baud rate of the board, in one place.
 * Nothing else in the firmware names a GPIO number.
 *
 * These are suggested assignments (plans/rp2350-feasibility.md fixes only the
 * peripherals, not the pins). Change them here to match the wiring.
 * Header pin numbers and alternate functions: docs/pico2w-pinout.svg.
 * Wiring diagram: docs/wiring.svg (generated by firmware/tools/wiring_svg.py,
 * update it when a pin here changes).
 *
 *   GP0   UART0 TX  -> TM210 RXD
 *   GP1   UART0 RX  <- TM210 TXD
 *   GP2   I2C1 SDA  <> BMP581
 *   GP3   I2C1 SCL  -> BMP581
 *   GP4   UART1 TX  -> UM980 COM1 RX
 *   GP5   UART1 RX  <- UM980 COM1 TX
 *   GP6   GPIO in   <- UM980 PPS
 *   GP7   GPIO in   <- BMP581 INT
 *   GP8   PIO UART RX <- Pi flow program TX (plans/optical-flow-aiding.md)
 *   GP10  PWM out   -> camera trigger (via a transistor to J3 TRIG+)
 *   GP11  GPIO in   <- camera strobe (J2 STROBE+, open collector, active low)
 *   GP12  GPIO in   <- speed input A: wheel / ISO 11786 pulses, or encoder A
 *   GP13  GPIO in   <- speed input B: quadrature encoder B (unused for one Hall)
 *                      (both behind an opto-isolated 12 V input stage,
 *                      plans/wheel-odometry-aiding.md)
 *   GP16  SPI0 RX   <- W5500 MISO   (Ethernet, when fitted)
 *   GP17  GPIO out  -> W5500 CS
 *   GP18  SPI0 SCK  -> W5500 SCLK
 *   GP19  SPI0 TX   -> W5500 MOSI
 *   GP20  GPIO out  -> W5500 RSTn
 *   GP21  GPIO in   <- W5500 INTn   (not used yet, polled)
 *   GP22            reserved: web-mode switch (plans/web-config-server.md)
 *   GP23/24/25/29   used by the CYW43439 on the Pico 2 W
 *
 * The UM980 module runs from 5 V. Check its UART and PPS logic level against
 * the Pico's 3.3 V GPIO before connecting it.
 */
#ifndef BOARD_PINS_H
#define BOARD_PINS_H

#include "hardware/i2c.h"
#include "hardware/spi.h"
#include "hardware/uart.h"

/* TM210 IMU on UART0 (plans/imu-tm210.md). */
#define PIN_TM210_UART        uart0
#define PIN_TM210_TX          0
#define PIN_TM210_RX          1
#define TM210_BAUD            921600

/* BMP581 barometer on I2C1 (firmware/drivers/bmp581). */
#define PIN_BMP581_I2C        i2c1
#define PIN_BMP581_SDA        2
#define PIN_BMP581_SCL        3
#define PIN_BMP581_INT        7
#define BMP581_I2C_HZ         400000

/* UM980 COM1 on UART1 (plans/gnss-um98x-config.md). */
#define PIN_UM980_UART        uart1
#define PIN_UM980_TX          4
#define PIN_UM980_RX          5
#define PIN_UM980_PPS         6
#define UM980_BAUD            460800

/* Optical flow from the Pi (plans/optical-flow-aiding.md, common/flow_link.h):
 * receive-only PIO UART, the camera trigger and its strobe. */
#define PIN_FLOW_RX           8
#define PIN_FLOW_TRIGGER      10
#define PIN_FLOW_STROBE       11

/* Wheel / ground-speed pulses (plans/wheel-odometry-aiding.md). One Hall
 * sensor or ISO 11786 signal on A, or a quadrature encoder on A and B. */
#define PIN_SPEED_A           12
#define PIN_SPEED_B           13

/* W5500 Ethernet on SPI0 (plans/ethernet-w5500-agopenweb.md), the pins of
 * WIZnet's W5500-EVB-Pico. Driven only while the web setting "Ethernet
 * fitted" is on; otherwise left as inputs. Do not assign them to anything
 * else. */
#define PIN_W5500_SPI         spi0
#define PIN_W5500_MISO        16
#define PIN_W5500_CS          17
#define PIN_W5500_SCK         18
#define PIN_W5500_MOSI        19
#define PIN_W5500_RST         20
#define PIN_W5500_INT         21

/* Reserved, not used by this build. Do not assign it to anything else. */
#define PIN_WEB_MODE_SWITCH   22

#endif /* BOARD_PINS_H */
